        "exam_code": "PRO192_SU26_FE",
        "content": "What is the output of the following code snippet?\n\n```\nint sum = 0;\nfor (int i = 0; i <= 10; i += 2) {\n    sum += (i % 2 == 0 ? 1 : -1);\n}\n```\n\nSystem.out.println(sum);",
